files.content:
[hidden] { display: none !important; }

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.card {
  background: #16213e;
  border: 3px solid #0f3460;
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 360px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
}

.title {
  color: #e94560;
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 16px;
  letter-spacing: 1px;
  font-weight: 700;
}

.display {
  background: #0f3460;
  color: #eaeaea;
  font-size: 1.25rem;
  text-align: center;
  padding: 16px;
  border-radius: 8px;
  margin-bottom: 20px;
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  letter-spacing: 2px;
  word-break: break-word;
}

.keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.key {
  background: #0f3460;
  color: #eaeaea;
  border: 2px solid #1a1a2e;
  border-radius: 8px;
  padding: 16px 0;
  font-size: 1.25rem;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
  min-height: 56px;
}

.key:hover:not(:disabled) {
  background: #1e4d7a;
}

.key:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.key:active:not(:disabled) {
  background: #e94560;
  transform: scale(0.96);
}

.key:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.key.action {
  background: #e94560;
  color: #fff;
}

.key.action:hover:not(:disabled) {
  background: #ff5c77;
}

.key.action:active:not(:disabled) {
  background: #c73550;
}

.status {
  text-align: center;
  margin-top: 16px;
  font-size: 1.125rem;
  font-weight: 600;
  min-height: 1.5em;
  color: #eaeaea;
}

.status.success {
  color: #4ade80;
}

.status.error {
  color: #e94560;
}

.status.locked {
  color: #fbbf24;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .key {
    padding: 12px 0;
    min-height: 48px;
    font-size: 1.125rem;
  }
  .keypad {
    gap: 8px;
  }
}

(function () {
  'use strict';

  var SECRET = '4271';
  var MAX_ATTEMPTS = 3;
  var LOCKOUT_MS = 10000;

  var input = '';
  var wrongCount = 0;
  var locked = false;
  var lockTimer = null;
  var countdownTimer = null;

  var display = document.getElementById('display');
  var statusEl = document.getElementById('status');
  var keypad = document.getElementById('keypad');
  var clearBtn = document.getElementById('clear');
  var enterBtn = document.getElementById('enter');
  var keys = Array.prototype.slice.call(keypad.querySelectorAll('.key'));

  function setStatus(text, type) {
    statusEl.textContent = text;
    statusEl.className = 'status' + (type ? ' ' + type : '');
  }

  function updateDisplay() {
    display.textContent = input ? input.replace(/[0-9]/g, '●') : 'Enter code';
  }

  function setControlsDisabled(disabled) {
    keys.forEach(function (btn) {
      btn.disabled = disabled;
    });
  }

  function startLockout() {
    locked = true;
    setControlsDisabled(true);
    var remaining = LOCKOUT_MS / 1000;
    setStatus('Locked. Try again in ' + remaining + 's', 'locked');
    countdownTimer = setInterval(function () {
      remaining -= 1;
      if (remaining > 0) {
        setStatus('Locked. Try again in ' + remaining + 's', 'locked');
      }
    }, 1000);
    lockTimer = setTimeout(function () {
      locked = false;
      wrongCount = 0;
      setControlsDisabled(false);
      clearInterval(countdownTimer);
      setStatus('Enter code', '');
      updateDisplay();
    }, LOCKOUT_MS);
  }

  function checkCode() {
    if (locked) return;
    if (input === SECRET) {
      setStatus('Unlocked', 'success');
      display.textContent = 'Unlocked';
      input = '';
      wrongCount = 0;
      setControlsDisabled(true);
      setTimeout(function () {
        setControlsDisabled(false);
        setStatus('Enter code', '');
        updateDisplay();
      }, 2000);
    } else {
      wrongCount += 1;
      input = '';
      updateDisplay();
      if (wrongCount >= MAX_ATTEMPTS) {
        startLockout();
      } else {
        setStatus('Wrong code (' + wrongCount + '/' + MAX_ATTEMPTS + ')', 'error');
      }
    }
  }

  function handleDigit(digit) {
    if (locked) return;
    if (input.length < 4) {
      input += digit;
      updateDisplay();
      setStatus('', '');
    }
  }

  keypad.addEventListener('click', function (e) {
    var btn = e.target.closest('button');
    if (!btn || btn.disabled) return;
    if (btn.dataset.digit !== undefined) {
      handleDigit(btn.dataset.digit);
    } else if (btn === clearBtn) {
      if (locked) return;
      input = '';
      updateDisplay();
      setStatus('', '');
    } else if (btn === enterBtn) {
      checkCode();
    }
  });

  document.addEventListener('keydown', function (e) {
    if (locked) return;
    if (/^[0-9]$/.test(e.key)) {
      handleDigit(e.key);
    } else if (e.key === 'Backspace' || e.key === 'Delete' || e.key.toLowerCase() === 'c') {
      input = '';
      updateDisplay();
      setStatus('', '');
    } else if (e.key === 'Enter') {
      checkCode();
    }
  });

  updateDisplay();
})();
